#include <stdio.h>
int main(){int n,i,bt[20],wt[20],tat[20];float aw=0,at=0;printf("Enter Number of Processes: ");scanf("%d",&n);for(i=0;i<n;i++){printf("Enter Burst Time for P%d: ",i+1);scanf("%d",&bt[i]);}wt[0]=0;for(i=1;i<n;i++)wt[i]=wt[i-1]+bt[i-1];printf("\nProcess\tBT\tWT\tTAT\n");for(i=0;i<n;i++){tat[i]=wt[i]+bt[i];aw+=wt[i];at+=tat[i];printf("P%d\t%d\t%d\t%d\n",i+1,bt[i],wt[i],tat[i]);}printf("\nAverage Waiting Time = %.2f\nAverage Turnaround Time = %.2f\n",aw/n,at/n);return 0;}